WITH store_summary AS (SELECT store_id, MAX(order_date) AS latest_order_date, MAX(discount) - MIN(discount) AS discount_range FROM orders GROUP BY store_id) SELECT s.city, s.region, ss.latest_order_date, ss.discount_range FROM stores s INNER JOIN store_summary ss ON s.id = ss.store_id WHERE ss.discount_range > 77 ORDER BY 4 DESC, city
